declare module '*.svg' {
  const content: string;
  export default content;
}

declare module '*.png' {
  const content: string;
  export default content;
}

declare module '*.jpg' {
  const content: string;
  export default content;
}

declare module '*.module.css' {
  const classes: { readonly [camelCaseKey: string]: string };
  export default classes;
}

declare module '*.css' {
  const content: string;
  export default content;
}
